def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_last, opp_last = history[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Pure always-cooperator: extract maximum late, but keep cooperation early
    if opp_d == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # Pure always-defector: never reward it
    if opp_c == 0:
        return 'D'

    # Opening: be cooperative and slightly forgiving
    if n < 4:
        if opp_last == 'D' and n >= 2:
            # punish but not too long
            if n >= 3 and opp[-2] == 'D':
                return 'D'
        return 'C'

    # Recent windows
    w = opp[-12:]
    w_d = w.count('D')
    w_c = len(w) - w_d

    # Detect opponent's propensity to punish our defection vs ignore it
    # (transition stats, only look at last 30 rounds for adaptivity)
    start = max(0, n - 31)
    c_after_c = 0
    c_after_d = 0  # opponent D after our D
    c_after_d_total = 0
    d_after_c_total = 0
    for i in range(start, n - 1):
        if me[i] == 'C':
            d_after_c_total += 1
            if opp[i + 1] == 'C':
                c_after_c += 1
        else:
            c_after_d_total += 1
            if opp[i + 1] == 'D':
                c_after_d += 1
    punish_rate = c_after_d / c_after_d_total if c_after_d_total > 0 else 0.0
    forgive_rate = c_after_c / d_after_c_total if d_after_c_total > 0 else 0.0

    # Strongly retaliatory opponent: cooperate to avoid cycles, unless very defective
    if punish_rate > 0.6:
        if w_d >= 6:
            return 'D'
        if my_last == 'D' and opp_last == 'D':
            return 'C'  # break retaliation cycles
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Exploitable / forgiving opponent: periodically probe
    if forgive_rate < 0.35 and n >= 15 and w_d <= 2:
        # They tend to keep cooperating after our defections: probe
        if my_last == 'C' and n % 7 == 0:
            return 'D'
        if my_last == 'D' and opp_last == 'C':
            return 'D'  # keep milking
        return 'C'

    # Mostly cooperative opponent: preserve mutual cooperation
    if w_d <= 1:
        if n >= 95:
            return 'D'
        return 'C'

    # Opponent in a defection streak: retaliate, but schedule a repair
    if opp_last == 'D':
        # count trailing opponent defections
        streak = 0
        for a in reversed(opp):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 4:
            return 'D'
        # after a short punishment, offer a repair
        if streak >= 2:
            # if we've already defected back at least once, try C to repair
            my_streak = 0
            for a in reversed(me):
                if a == 'D':
                    my_streak += 1
                else:
                    break
            if my_streak >= 2:
                return 'C'
            return 'D'
        # single defection: retaliate once, then forgive
        return 'D'

    # Opponent cooperated last round: cooperate, but occasionally test if they
    # appear to be a pushover
    if n >= 20 and w_d <= 3 and forgive_rate < 0.4 and n % 9 == 0:
        return 'D'
    return 'C'
